    19	  } catch {
    20	    return true;
    21	  }
    22	}
    23	
    24	// home → voice call with Pawse → advice
    25	//   → "call the vet": clinic list → Pawse calls the chosen clinic
    26	//   → "call the insurer": Pawse calls the insurer
    27	//   → plan (summary)
    28	export default function App() {
    29	  const [view, setView] = useState('home'); // home | voice | clinics | phone | plan
    30	  const [lang, setLangState] = useState(detectLang);
    31	  const [triage, setTriage] = useState(null);
    32	  const [vet, setVet] = useState(null);
    33	  const [insurance, setInsurance] = useState(null);
    34	  const [clinic, setClinic] = useState(null);
    35	  const [target, setTarget] = useState(null);
    36	  const [rehearsal, setRehearsal] = useState(false);
    37	  const [gradiumOn, setGradiumOnState] = useState(loadGradiumChoice);
    38	  const [voiceStatus, setVoiceStatus] = useState(null);
    39	
    40	  const setGradiumOn = (on) => {
    41	    setGradiumOnState(on);
    42	    try {
    43	      localStorage.setItem(GRADIUM_KEY, on ? '1' : '0');
    44	    } catch {
    45	      /* storage unavailable */
    46	    }
    47	  };
    48	
    49	  // Live phone calls only: is Gradium configured, and does this session have its own German voice?
    50	  useEffect(() => {
    51	    if (!IS_LIVE_PHONE) return undefined;
    52	    let alive = true;
    53	    fetch(`${PHONE_AGENT_URL || ''}/api/v1/voice/status`)
    54	      .then((r) => (r.ok ? r.json() : null))
    55	      .then((s) => alive && s && setVoiceStatus(s))
    56	      .catch(() => {});
    57	    return () => {
    58	      alive = false;
    59	    };
    60	  }, []);
    61	  // Unknown status: still offer Gradium; the call falls back to the browser voice on 503.
    62	  const gradiumAvailable = IS_LIVE_PHONE && (!voiceStatus || voiceStatus.gradium_configured === true);
    63	  const ownVoice = !!(voiceStatus && voiceStatus.my_voice_ready);
    64	
    65	  const t = strings[lang] || strings.en;
    66	  const Handoff = IS_LIVE_PHONE && !rehearsal ? LiveHandoff : PhoneCall;
    67	
    68	  const setLang = (l) => {
    69	    setLangState(l);
    70	    saveLang(l);
    71	  };
    72	
    73	  useEffect(() => {
    74	    document.documentElement.lang = lang === 'zh' ? 'zh-CN' : lang;
    75	  }, [lang]);
    76	
    77	  const startCall = () => {
    78	    primeSpeech(); // unlock speech on iOS while we are inside the tap
    79	    setTriage(null);
    80	    setVet(null);
    81	    setInsurance(null);
    82	    setClinic(null);
    83	    setView('voice');
    84	  };
    85	
    86	  const call = (to) => {
    87	    setRehearsal(false);
    88	    primeSpeech();
    89	    if (to === 'vet') {
    90	      setView('clinics');
    91	      return;
    92	    }
    93	    setTarget(to);
    94	    setView('phone');
    95	  };
    96	
    97	  const pickClinic = (c) => {
    98	    setRehearsal(false);
    99	    primeSpeech();
   100	    setClinic(c);
   101	    setTarget('vet');
   102	    setView('phone');
   103	  };
   104	
   105	  const callDone = (result) => {
   106	    if (result && target === 'vet') setVet(result);
   107	    if (result && target === 'insurance') setInsurance(result);
   108	    setView(triage ? 'plan' : 'home');
   109	  };
   110	
   111	  if (view === 'ownvoice') return <OwnVoice onBack={() => setView('home')} />;
   112	  if (view === 'voice') {
   113	    return (
   114	      <VoiceCall
   115	        t={t}
   116	        lang={lang}
   117	        triage={triage}
   118	        vet={vet}
   119	        insurance={insurance}
   120	        onTriage={setTriage}
   121	        onCall={call}
   122	        onEnd={() => setView(triage ? 'plan' : 'home')}
   123	      />
   124	    );
   125	  }
   126	  if (view === 'clinics') {
   127	    // Going back from the list never restarts the voice call: show the plan instead.
   128	    return <ClinicList t={t} lang={lang} triage={triage} onPick={pickClinic} onBack={() => setView(triage ? 'plan' : 'home')} />;
   129	  }
   130	  if (view === 'phone') {
   131	    return (
   132	      <Handoff
   133	        key={`${target}-${clinic ? clinic.id : ''}`}
   134	        t={t}
   135	        lang={lang}
   136	        target={target}
   137	        clinic={target === 'vet' ? clinic : null}
   138	        gradium={gradiumAvailable ? { on: gradiumOn, ownVoice, set: setGradiumOn } : null}
   139	        context={{
   140	          gradiumConsent: gradiumAvailable && gradiumOn,
   141	          voice: ownVoice ? 'my_voice' : 'standard',
   142	          summary: buildSummary({ lang, triage, vet, insurance }),
   143	          clinic: target === 'vet' ? clinic : undefined,
   144	          estimate: vet ? vet.estimate : undefined,
   145	          homeVisitFee: vet ? vet.homeVisitFee : undefined,
   146	        }}
   147	        onDone={callDone}
   148	        onRehearse={() => { setGradiumOn(false); setRehearsal(true); }}
   149	      />
   150	    );
   151	  }
   152	  if (view === 'plan' && triage) {
   153	    return (
   154	      <Plan
   155	        t={t}
   156	        lang={lang}
   157	        triage={triage}
   158	        vet={vet}
   159	        insurance={insurance}
   160	        onCall={call}
   161	        onRestart={() => setView('home')}
   162	      />
   163	    );
   164	  }
   165	  return <Home t={t} lang={lang} setLang={setLang} onStart={startCall} onOwnVoice={() => setView('ownvoice')} />;
   166	}
   167	// Central switches. Set them in .env.local (see .env.example).
   168	// import.meta.env is undefined outside Vite (e.g. plain-Node checks), so guard it.
   169	const env = (typeof import.meta !== 'undefined' && import.meta.env) || {};
   170	
   171	const param = (k) => {
   172	  try {
   173	    return new URLSearchParams(window.location.search).get(k);
   174	  } catch {
   175	    return null;
   176	  }
   177	};
   178	
   179	/** 'mock' = scripted demo (default). 'live' = the Pawse backend. "?live=1" in the URL switches all three at runtime. */
   180	const DEMO_ALL = param('demo') === '1';
   181	const LIVE_ALL = !DEMO_ALL && param('live') === '1';
   182	export const VOICE_AGENT = DEMO_ALL ? 'mock' : LIVE_ALL ? 'live' : env.VITE_VOICE_AGENT || 'mock';
   183	export const CLINIC_SEARCH = DEMO_ALL ? 'mock' : LIVE_ALL ? 'live' : env.VITE_CLINIC_SEARCH || 'mock';
   184	export const PHONE_AGENT = DEMO_ALL ? 'mock' : LIVE_ALL ? 'live' : env.VITE_PHONE_AGENT || 'mock';
   185	
   186	export const VOICE_AGENT_URL = env.VITE_VOICE_AGENT_URL || '';
   187	export const CLINIC_SEARCH_URL = env.VITE_CLINIC_SEARCH_URL || '';
   188	export const PHONE_AGENT_URL = env.VITE_PHONE_AGENT_URL || '';
   189	
   190	/** Mock playback speed. "?speed=3" in the URL plays the demo 3x faster (handy for rehearsing). */
   191	export const MOCK_SPEED = (() => {
   192	  const v = Number(param('speed'));
   193	  return v > 0 ? v : 1;
   194	})();
   195	import { VOICE_AGENT, CLINIC_SEARCH, PHONE_AGENT, MOCK_SPEED } from '../config.js';
   196	import { createMockVoiceAgent } from './mockVoiceAgent.js';
   197	import { createGeminiLiveAgent } from './geminiLiveAgent.js';
   198	import { createLiveVoiceAgent } from './liveVoiceAgent.js';
   199	import { mockSearchClinics } from './mockClinicSearch.js';
   200	import { liveSearchClinics } from './liveClinicSearch.js';
   201	import { createMockPhoneCall } from './mockPhoneAgent.js';
   202	import { createLivePhoneCall } from './livePhoneAgent.js';
   203	
   204	export const IS_LIVE_VOICE = VOICE_AGENT === 'live';
   205	export const IS_LIVE_CLINICS = CLINIC_SEARCH === 'live';
   206	export const IS_LIVE_PHONE = PHONE_AGENT === 'live';
   207	export const IS_MOCK = !IS_LIVE_VOICE || !IS_LIVE_CLINICS || !IS_LIVE_PHONE;
   208	
   209	/** Which voice path runs: 'mock' (scripted), 'rest' (transcribe + care over REST) or 'native' (Gemini Live audio). */
   210	export const VOICE_PATH = !IS_LIVE_VOICE ? 'mock' : new URLSearchParams(globalThis.location?.search || '').get('voice') === 'rest' ? 'rest' : 'native';
   211	
   212	/** The page opens the microphone only if the active voice agent wants audio. */
   213	export const VOICE_WANTS_AUDIO = IS_LIVE_VOICE;
   214	
   215	/** 1. Voice conversation with Pawse. */
   216	export function createVoiceAgent(opts) {
   217	  return IS_LIVE_VOICE ? (new URLSearchParams(globalThis.location?.search || '').get('voice') === 'rest' ? createLiveVoiceAgent(opts) : createGeminiLiveAgent(opts)) : createMockVoiceAgent({ speed: MOCK_SPEED, ...opts });
   218	}
   219	
   220	/** 2. Nearby vet clinics. */
   221	export function searchClinics(opts) {
   222	  return IS_LIVE_CLINICS ? liveSearchClinics(opts) : mockSearchClinics({ speed: MOCK_SPEED, ...opts });
   223	}
   224	
   225	/** 3. Pawse calls the clinic or the insurer. */
   226	export function createPhoneCall(opts) {
   227	  return IS_LIVE_PHONE ? createLivePhoneCall(opts) : createMockPhoneCall({ speed: MOCK_SPEED, ...opts });
