  1	import { GoogleGenAI } from '@google/genai';
  2	import { VOICE_AGENT_URL } from '../config.js';
  3	import { mapCareResult } from './liveVoiceAgent.js';
  4	import { createNativeAudio } from './nativeAudio.js';
  5	import { loadInsuranceProfile, saveInsuranceProfile } from './insuranceProfile.js';
  6	import { getLocation } from './location.js';
  7	
  8	// Injectable transport/audio factories keep protocol tests offline and deterministic.
  9	export function createGeminiLiveAgent({lang='en',shareWithGemini=false,
 10	  clientFactory=options=>new GoogleGenAI(options), audioFactory=createNativeAudio, locate=getLocation}={}) {
 11	  const listeners=new Set(), pending=new Set(), toolIds=new Set(), cancelledTools=new Set();
 12	  let started=false, ended=false, session=null, audio=null, media=null, muted=true, outputMuted=false, timer=null;
 13	  let audioEpoch=0;
 14	  let inputText='',outputText='', userOpen=false, playback=Promise.resolve();
 15	  // The owner's words stream in as a partial caption; the first sign of Pawse answering seals them.
 16	  const sealUser=()=>{if(userOpen){userOpen=false;emit({type:'transcript',role:'user',text:inputText,partial:false});}};
 17	  const emit=e=>{if(!ended||e.type==='ended') for(const fn of listeners){try{fn(e);}catch{}}};
 18	  const error=message=>emit({type:'error',message});
 19	  async function post(path,body){
 20	    const ctl=new AbortController();pending.add(ctl);const timeout=setTimeout(()=>ctl.abort(),55000);
 21	    try{
 22	      const r=await fetch(`${VOICE_AGENT_URL || ''}/api/v1/live/${path}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal:ctl.signal});
 23	      if(!r.ok){const j=await r.json().catch(()=>({}));throw Error(typeof j.detail==='string'?j.detail:`Live request failed (${r.status})`);}
 24	      return await r.json();
 25	    }finally{clearTimeout(timeout);pending.delete(ctl);}
 26	  }
 27	  function end(){
 28	    if(ended)return;ended=true;clearTimeout(timer);
 29	    for(const c of pending)c.abort();pending.clear();
 30	    try{session?.close();}catch{}session=null;
 31	    media?.getTracks().forEach(t=>t.stop());media=null;
 32	    audio?.close().catch(()=>{});emit({type:'ended'});
 33	  }
 34	  function send(payload){if(!ended&&session)session.sendRealtimeInput(payload);}
 35	  async function tool(call){
 36	    if(!call.id||toolIds.has(call.id)||ended)return;
 37	    toolIds.add(call.id);
 38	    if(toolIds.size>100){error('Session tool limit reached. Start a new session.');end();return;}
 39	    emit({type:'tool_status',name:call.name,state:'running'});
 40	    let response;
 41	    try{
 42	      // Clinics need a location; the browser's permission prompt is the owner's consent for it.
 43	      const location=call.name==='assess_and_find_vets'?await locate().catch(()=>null):null;
 44	      if(ended||cancelledTools.has(call.id))return;
 45	      const context={language:lang,share_location:!!location,insurance:loadInsuranceProfile(),...(location?{location}:{})};
 46	      const result=await post('tool-calls',{id:call.id,name:call.name,args:call.args||{},share_with_gemini:true,context});
 47	      response=result.response;
 48	      if(ended||cancelledTools.has(call.id))return;
 49	      const ui=result.ui;
 50	      if(ui?.action==='save_insurance_profile')saveInsuranceProfile(ui);
 51	      if(ui?.care){emit({type:'agents',trace:ui.trace||[],actions:[]});emit(mapCareResult(ui.care,lang));}
 52	      else if(ui)emit({type:'tool_result',name:call.name,ui});
 53	    }catch(e){response={error:'tool_unavailable',detail:e.message};}
 54	    if(!ended&&!cancelledTools.has(call.id)&&session){
 55	      session.sendToolResponse({functionResponses:[{id:call.id,name:call.name,response}]});
 56	      emit({type:'tool_status',name:call.name,state:response?.error?'unavailable':'complete'});
 57	    }
 58	  }
 59	  function message(msg){
 60	    if(ended)return;
 61	    try{
 62	      for(const id of msg.toolCallCancellation?.ids||[])cancelledTools.add(id);
 63	      const c=msg.serverContent;
 64	      if(c?.interrupted){audioEpoch++;audio.flush();sealUser();inputText='';outputText='';}
 65	      if(c?.inputTranscription?.text){inputText+=c.inputTranscription.text;userOpen=true;emit({type:'transcript',role:'user',text:inputText,partial:true});}
 66	      if(c?.outputTranscription?.text){sealUser();outputText+=c.outputTranscription.text;emit({type:'transcript',role:'ai',text:outputText});}
 67	      for(const part of c?.modelTurn?.parts||[]){
 68	        const data=part.inlineData;
 69	        if(data?.data&&data.mimeType?.startsWith('audio/pcm')){
 70	          const rate=Number(/rate=(\d+)/.exec(data.mimeType)?.[1]||24000);
 71	          const epoch=audioEpoch;
 72	          playback=playback.then(()=>{if(!ended && epoch===audioEpoch)return audio.play(data.data,rate);}).catch(()=>{error('Native audio playback failed. Restart the session.');end();});
 73	        }
 74	      }
 75	      if(c?.turnComplete){sealUser();inputText='';outputText='';emit({type:'listening',on:!muted});}
 76	      if(msg.toolCall)sealUser();
 77	      for(const call of msg.toolCall?.functionCalls||[]) void tool(call).catch(()=>error('Tool response could not be delivered.'));
 78	      if(msg.goAway){error('Live session is ending. Start a new conversation.');end();}
 79	    }catch{error('Live response could not be processed.');end();}
 80	  }
 81	  return {
 82	    wantsAudio:true,on(fn){listeners.add(fn);return()=>listeners.delete(fn);},
 83	    async start(){
 84	      if(started||ended)return;
 85	      if(!shareWithGemini){error('Confirm sharing with Gemini before starting.');return;}
 86	      started=true;
 87	      try{
 88	        audio=audioFactory(frame=>{if(!muted&&session&&!ended)send({audio:{data:frame,mimeType:'audio/pcm;rate=16000'}});}, speaking=>emit({type:'speaking',who:speaking?'ai':'none'}));
 89	        audio.setMuted(outputMuted);
 90	        const token=await post('tokens',{language:lang,share_with_gemini:true});if(ended)return;
 91	        const ai=clientFactory({apiKey:token.token,httpOptions:{apiVersion:token.api_version}});
 92	        const connected=await ai.live.connect({model:token.model,config:{responseModalities:['AUDIO']},callbacks:{onmessage:message,onerror:()=>{error('Gemini Live connection failed. Restart or use text fallback.');end();},onclose:()=>{if(!ended){error('Gemini Live disconnected. Start a new session.');end();}}}});
 93	        if(ended){connected.close();return;}session=connected;
 94	        timer=setTimeout(()=>{error('Session time limit reached. Start a new conversation.');end();},8*60*1000);
 95	        if(media&&!muted)await audio.attach(media);
 96	        emit({type:'listening',on:!muted});
 97	        send({text:'Introduce yourself briefly as Pawse, an AI cat-care assistant, and ask how you can help. Do not invent a concern.'});
 98	      }catch(e){if(!ended){error(e.message?.includes('key')?'Live audio could not start. Check server configuration.':e.message||'Live audio could not start.');end();}}
 99	    },
100	    end,
101	    sendText(text){if(!session){error('Wait for the Live connection, then try again.');return;}const s=String(text||'').trim();if(!s||s.length>4000)return;audio.flush();userOpen=false;inputText='';outputText='';send({text:s});emit({type:'transcript',role:'user',text:s});},
102	    async sendImage(file){
