113	export function pcm16Base64(samples) {
114	  const bytes = new Uint8Array(samples.length * 2), view = new DataView(bytes.buffer);
115	  for (let i=0;i<samples.length;i++) view.setInt16(i*2, Math.round(Math.max(-1,Math.min(1,samples[i]))*32767), true);
116	  let s=''; for (let i=0;i<bytes.length;i+=8192) s+=String.fromCharCode(...bytes.subarray(i,i+8192));
117	  return btoa(s);
118	}
119	export function decodePCM(data) {
120	  const raw=atob(data); if (raw.length%2) throw Error('Invalid PCM frame');
121	  const bytes=Uint8Array.from(raw,c=>c.charCodeAt(0)), view=new DataView(bytes.buffer), out=new Float32Array(bytes.length/2);
122	  for(let i=0;i<out.length;i++) out[i]=view.getInt16(i*2,true)/32768;
123	  return out;
124	}
125	export function createNativeAudio(onFrame, onSpeaking) {
126	  const AC=globalThis.AudioContext || globalThis.webkitAudioContext;
127	  if (!AC) throw Error('Native audio is unavailable in this browser.');
128	  const output=new AC({sampleRate:24000});
129	  output.resume().catch(()=>{});
130	  let input=null, source=null, worklet=null, stream=null, closed=false, muted=false, inputGeneration=0, attachRequest=0;
131	  let epoch=0; let next=0; const playing=new Set();
132	  function flush() { epoch++; for(const s of playing) {try{s.stop();}catch{}} playing.clear();next=0;onSpeaking(false); }
133	  async function detach() {
134	    inputGeneration++;
135	    if(worklet) {worklet.port.onmessage=null;worklet.disconnect();worklet=null;}
136	    source?.disconnect();source=null;
137	    stream?.getTracks().forEach(t=>t.stop());stream=null;
138	    if(input) {const c=input;input=null;await c.close().catch(()=>{});}
139	  }
140	  return {
141	    async attach(media) {
142	      if(media===stream) return;
143	      const request=++attachRequest;
144	      await detach(); if(!media||closed||request!==attachRequest) return;
145	      const generation=++inputGeneration;
146	      stream=media; input=new AC({sampleRate:16000}); const ctx=input;
147	      await ctx.audioWorklet.addModule(new URL('../audio/pcm-worklet.js', import.meta.url));
148	      if(closed||generation!==inputGeneration) return;
149	      await ctx.resume();
150	      if(closed||generation!==inputGeneration) return;
151	      source=ctx.createMediaStreamSource(media);worklet=new AudioWorkletNode(ctx,'pawse-pcm');
152	      worklet.port.onmessage=e=>{if(!closed) onFrame(pcm16Base64(e.data));};
153	      source.connect(worklet); worklet.connect(ctx.destination); // processor outputs silence
154	    },
155	    async play(data, rate=24000) {
156	      if(closed||muted) return;
157	      if(!Number.isFinite(rate)||rate<8000||rate>48000) throw Error('Invalid audio rate');
158	      const samples=decodePCM(data);
159	      if(!samples.length) return;
160	      if(Math.max(next,output.currentTime)+samples.length/rate-output.currentTime>15) throw Error('Audio playback cannot keep up. Restart the session.');
161	      const generation=epoch;await output.resume(); if(closed||muted||generation!==epoch) return;
162	      const buffer=output.createBuffer(1,samples.length,rate);buffer.copyToChannel(samples,0);
163	      const node=output.createBufferSource();node.buffer=buffer;node.connect(output.destination);
164	      node.onended=()=>{playing.delete(node);node.disconnect();if(!playing.size) onSpeaking(false);};
165	      playing.add(node);onSpeaking(true);next=Math.max(next,output.currentTime);node.start(next);next+=buffer.duration;
166	    },
167	    flush,
168	    setMuted(value){muted=value;if(value)flush();},
169	    async close(){closed=true;flush();await detach();await output.close().catch(()=>{});},
170	  };
171	}
172	// SLOT 2: clinic search against the Pawse FastAPI backend.
173	// Endpoint: POST /api/v1/clinics/search (same origin; Vite proxies /api to :8765). It is separate from
174	// /api/v1/care/requests, so it never waits on the voice agent's advice request still in flight.
175	// Base URL defaults to ''; override with VITE_CLINIC_SEARCH_URL (e.g. https://pawse.example.com).
176	//
177	// Consent: only coordinates and location-sharing consent are sent, never symptoms.
178	// The backend enforces the consent server-side as well.
179	
180	import { CLINIC_SEARCH_URL } from '../config.js';
181	
182	const ENDPOINT = '/api/v1/clinics/search';
183	
184	export function haversineKm(a, b) {
185	  const rad = (d) => (d * Math.PI) / 180;
186	  const dLat = rad(b.lat - a.lat);
187	  const dLng = rad(b.lng - a.lng);
188	  const h = Math.sin(dLat / 2) ** 2 + Math.cos(rad(a.lat)) * Math.cos(rad(b.lat)) * Math.sin(dLng / 2) ** 2;
189	  return 2 * 6371.0088 * Math.asin(Math.min(1, Math.sqrt(h)));
190	}
191	
192	/** Map one backend Clinic to the frontend Clinic. Never invents hours or distance. */
193	export function mapClinic(c, location) {
194	  let distanceKm = Number.NaN; // unknown; the page shows a dash
195	  if (typeof c.distance_km === 'number') distanceKm = c.distance_km;
196	  else if (location && c.location && typeof c.location.lat === 'number') distanceKm = haversineKm(location, c.location);
197	  const openUnknown = typeof c.open_now !== 'boolean';
198	  const out = {
199	    id: c.id,
200	    name: c.name,
201	    address: c.address || '',
202	    distanceKm,
203	    openNow: c.open_now === true,
204	    hoursText: openUnknown ? 'Hours unknown, call to confirm' : (c.open_now ? 'Reported open now by provider, call to confirm' : 'Reported closed by provider'),
205	  };
206	  if (openUnknown) out.openUnknown = true;
207	  if (c.emergency_service === 'provider_reported') out.emergency = true;
208	  if (typeof c.rating === 'number') out.rating = c.rating;
209	  if (c.maps_url) out.mapsUrl = c.maps_url;
210	  if (c.phone) out.phone = c.phone;
211	  if (/^tel:\+[1-9]\d{6,14}$/.test(c.call_url || '')) out.callUrl = c.call_url;
212	  out.source = c.source; out.retrievedAt = c.retrieved_at;
213	  out.reasons = c.reasons || [];
214	  out.website = c.website;
215	  if (Array.isArray(c.opening_hours) && c.opening_hours.length) out.hoursList = c.opening_hours.map(String);
216	  return out;
217	}
218	
219	export async function liveSearchClinics({ lang = 'en', location = null, triage = null } = {}) {
220	  if (!location) throw new Error('Location is needed to find nearby clinics (permission denied or unavailable).');
221	  const body = {
222	    language: /^[a-z]{2}$/.test(lang) ? lang : 'en',
223	    location: { lat: location.lat, lng: location.lng },
224	    share_location: true,
225	  };
226	  const res = await fetch((CLINIC_SEARCH_URL || '') + ENDPOINT, {
227	    method: 'POST',
228	    headers: { 'Content-Type': 'application/json' },
229	    body: JSON.stringify(body),
230	  });
231	  if (!res.ok) {
232	    const error = await res.json().catch(() => ({}));
233	    throw new Error(typeof error.detail === 'string' ? error.detail : `Clinic search failed (${res.status})`);
234	  }
235	  const data = await res.json();
236	  const raw = Array.isArray(data && data.clinics) ? data.clinics : [];
237	  if (!raw.length) {
238	    const why = (data && data.warnings && data.warnings.join(', ')) || 'no details';
239	    throw new Error(`No clinics returned by the backend (clinic provider not configured or unavailable: ${why}).`);
240	  }
241	  const clinics = raw.map((c) => mapClinic(c, location));
242	  // Preserve server ranking (opening status, distance, rating).
243	  return { clinics };
244	}
245	// Which AI / provider runs each step, derived from what actually happens at runtime.
246	// Nothing here is a claim: model ids come from GET /api/v1/capabilities, clinic sources from the
247	// clinics the backend returned, the voice from what the phone agent really played. Pure functions
248	// so a plain-Node check can pin the mapping. A provider is { step, key, model?, name? }; the page
249	// turns key/step into text through t.prov (see i18n.js).
250	
251	let capsPromise = null;
252	
253	/** Capabilities once per page load. Resolves null if the backend is unreachable (badges then omit model ids). */
254	export function loadCapabilities(base = '', fetchImpl = globalThis.fetch) {
255	  if (!capsPromise) {
256	    capsPromise = Promise.resolve()
257	      .then(() => fetchImpl(`${base}/api/v1/capabilities`))
258	      .then((r) => (r && r.ok ? r.json() : null))
259	      .then((d) => (d && typeof d === 'object' ? d : null))
260	      .catch(() => null);
261	  }
262	  return capsPromise;
263	}
264	
265	export function resetCapabilitiesCache() {
266	  capsPromise = null;
267	}
268	
269	const model = (caps, k) => (caps && caps.models && typeof caps.models[k] === 'string' ? caps.models[k] : undefined);
270	
271	/** Browser speech: `v` is { available, name } from speech.resolveVoiceName; muted silences it. */
272	export function browserVoice(v, muted = false) {
273	  if (muted) return { step: 'voice', key: 'muted' };
274	  if (!v || !v.available) return { step: 'voice', key: 'no_voice' };
275	  return { step: 'voice', key: 'browser_voice', name: v.name || undefined };
276	}
277	
278	/** Voice call with Pawse. path: 'mock' | 'rest' (transcribe + care REST) | 'native' (Gemini Live). */
279	export function voiceCallProviders({ path, caps, browser, muted = false }) {
280	  if (path === 'mock') return [{ step: 'conversation', key: 'scripted' }, browserVoice(browser, muted)];
281	  if (path === 'native') {
282	    return [
283	      { step: 'conversation', key: 'gemini_live', model: model(caps, 'live') },
284	      { step: 'care', key: 'gemini', model: model(caps, 'care') },
285	      muted ? { step: 'voice', key: 'muted' } : { step: 'voice', key: 'gemini_native_voice', model: model(caps, 'live') },
286	    ];
287	  }
288	  return [
289	    { step: 'transcription', key: 'gemini', model: model(caps, 'voice') },
290	    { step: 'care', key: 'gemini', model: model(caps, 'care') },
291	    browserVoice(browser, muted),
292	  ];
293	}
294	
295	const CLINIC_KEYS = { google_places: 'places', gemini_maps: 'gemini_maps', mapify: 'mapify', openstreetmap: 'osm' };
296	
297	/** Clinic search. `clinics` are the mapped results (each has .source from the backend). */
298	export function clinicProviders({ live, clinics = [], failed = false }) {
299	  if (!live) return [{ step: 'clinics', key: 'demo' }];
300	  const sources = [...new Set(clinics.map((c) => c && c.source).filter(Boolean))];
301	  if (failed || !sources.length) return [{ step: 'clinics', key: 'none' }];
