305	/**
306	 * Pawse's own voice on a phone call. voice = { voice: 'gradium'|'browser'|'off', variant, name }
307	 * (the event the live phone agent emits). Callee replies are always simulated.
308	 */
309	export function phoneVoice(voice, browser) {
310	  if (!voice || voice.voice === 'browser') return browserVoice(voice && voice.name ? { available: true, name: voice.name } : browser);
311	  if (voice.voice === 'off') return { step: 'voice', key: 'muted' };
312	  return { step: 'voice', key: voice.variant === 'my_voice' ? 'gradium_own' : 'gradium_standard' };
313	}
314	
315	export function phoneProviders({ live, target, voice, browser }) {
316	  const out = [{ step: 'script', key: live ? 'backend_script' : 'scripted' }, phoneVoice(voice, browser), { step: 'callee', key: 'simulated' }];
317	  if (live) out.push({ step: 'logic', key: target === 'insurance' ? 'rules_avb' : 'rules' });
318	  return out;
319	}
