321	/** Live phone handoff page (draft, audio, evidence). */
322	export function handoffProviders({ caps, voice, audioReady, target }) {
323	  const out = [{ step: 'draft', key: 'gemini', model: model(caps, 'voice') }];
324	  out.push({ step: 'voice', key: voice === 'my_voice' ? 'gradium_own' : 'gradium_standard', pending: !audioReady });
325	  if (target === 'insurance') out.push({ step: 'evidence', key: 'avb_search' });
