330	/** Voice descriptor the live phone agent emits; pure so the fallback switch is testable. */
331	export function phoneVoiceEvent({ gradiumOk, muted, variant, browser }) {
332	  if (muted) return { type: 'provider', step: 'voice', voice: 'off' };
333	  if (gradiumOk) return { type: 'provider', step: 'voice', voice: 'gradium', variant: variant === 'my_voice' ? 'my_voice' : 'standard' };
334	  return { type: 'provider', step: 'voice', voice: 'browser', name: browser && browser.available ? browser.name : undefined };
335	}
336	// One source clone and one German candidate per run; poll only the read endpoint.
337	export async function prepareGermanPreview({api, profile, sample, language, signal, onProfile, onStage, wait=delay}) {
338	  let p=profile;
339	  if(!p.source_id){
340	    onStage('Uploading your recording and cloning your voice…');
341	    p=await api('clone',{audio:{data:sample},sample_language:language,own_voice_consent:true,share_with_gradium:true},false,signal);
342	    onProfile(p);
343	  }
344	  if(!p.german_voice_id&&!p.candidate_pending){
345	    onStage('Your source voice is saved. Creating its German version…');
346	    p=await api('localizations',{share_with_gradium:true},false,signal);onProfile(p);
347	  }
348	  for(let i=0;!p.german_voice_id&&!p.candidate_ready&&i<20;i++){
349	    onStage('Gradium is preparing your German voice. Checking readiness…');
350	    await wait(3000,signal);
351	    p=await api('localizations/current',null,false,signal);onProfile(p);
352	  }
353	  if(!p.german_voice_id&&!p.candidate_ready)throw Error('Your German voice is still preparing. Click Continue to check again; do not record another sample.');
354	  onStage('Generating your German audio preview…');
355	  const audio=await api('preview',{share_with_gradium:true},true,signal);
356	  onStage('German preview ready. Press Play, then approve it if it sounds like you.');
357	  return audio;
358	}
359	function delay(ms,signal){return new Promise((resolve,reject)=>{
360	  if(signal?.aborted)return reject(new DOMException('Aborted','AbortError'));
361	  const abort=()=>{clearTimeout(timer);reject(new DOMException('Aborted','AbortError'));};
362	  const timer=setTimeout(()=>{signal?.removeEventListener('abort',abort);resolve();},ms);
363	  signal?.addEventListener('abort',abort,{once:true});
364	});}
365	// The owner's insurer and plan, as they told Pawse. Stored on this device only; never proof of cover.
366	const KEY = 'pawse.insurance';
367	
368	function clean(value, max) {
369	  return typeof value === 'string' ? value.trim().slice(0, max) : '';
370	}
371	
372	export function normalizeInsuranceProfile(raw) {
373	  const company = clean(raw?.company, 100);
374	  if (!company) return null;
375	  const plan = clean(raw?.plan, 120);
376	  return plan ? { company, plan } : { company };
377	}
378	
379	export function loadInsuranceProfile(storage = globalThis.localStorage) {
380	  try {
381	    return normalizeInsuranceProfile(JSON.parse(storage?.getItem(KEY) || 'null'));
382	  } catch {
383	    return null;
384	  }
385	}
