387	export function saveInsuranceProfile(raw, storage = globalThis.localStorage) {
388	  const profile = normalizeInsuranceProfile(raw);
389	  try {
390	    if (profile) storage?.setItem(KEY, JSON.stringify(profile));
391	    else storage?.removeItem(KEY);
392	  } catch {}
