  1	import { useEffect, useRef, useState } from 'react';
  2	import Avatar from '../components/Avatar.jsx';
  3	import Icon from '../components/Icon.jsx';
  4	import PlanPanel from '../components/PlanPanel.jsx';
  5	import useUserMedia from '../hooks/useUserMedia.js';
  6	import useMicLevel from '../hooks/useMicLevel.js';
  7	import ProviderChips from '../components/ProviderChips.jsx';
  8	import { createVoiceAgent, VOICE_WANTS_AUDIO, IS_LIVE_VOICE, VOICE_PATH } from '../agents/index.js';
  9	import { isSpeechMuted, setSpeechMuted, resolveVoiceName, onVoicesChanged } from '../agents/speech.js';
 10	import { loadCapabilities, voiceCallProviders } from '../agents/providers.js';
 11	import { VOICE_AGENT_URL } from '../config.js';
 12	import { validateTriage } from '../contracts.js';
 13	
 14	function fmt(sec) {
 15	  return `${String(Math.floor(sec / 60)).padStart(2, '0')}:${String(sec % 60).padStart(2, '0')}`;
 16	}
 17	
 18	// Voice first. The camera and photos are optional extras the user can add any time.
 19	export default function VoiceCall({ t, lang, triage, vet, insurance, onTriage, onCall, onEnd }) {
 20	  const [consent, setConsent] = useState(false);
 21	  const [toolResults, setToolResults] = useState([]);
 22	  const [trace, setTrace] = useState([]);
 23	  const [camOn, setCamOn] = useState(false);
 24	  const [facing, setFacing] = useState('environment');
 25	  const [micOn, setMicOn] = useState(!IS_LIVE_VOICE);
 26	  const [soundOn, setSoundOn] = useState(!isSpeechMuted());
 27	  const [aiLine, setAiLine] = useState('');
 28	  const [userLine, setUserLine] = useState('');
 29	  const [userPartial, setUserPartial] = useState(false);
 30	  const [transcribing, setTranscribing] = useState(false);
 31	  const [speaking, setSpeaking] = useState('none');
 32	  const [listening, setListening] = useState(false);
 33	  const [chips, setChips] = useState([]);
 34	  const [draft, setDraft] = useState('');
 35	  const [photos, setPhotos] = useState([]); // { url, received }
 36	  const [error, setError] = useState('');
 37	  const [sheetOpen, setSheetOpen] = useState(true);
 38	  const [secs, setSecs] = useState(0);
 39	  const [caps, setCaps] = useState(null);
 40	  const [browser, setBrowser] = useState(() => resolveVoiceName(lang));
 41	
 42	  const videoRef = useRef(null);
 43	  const fileRef = useRef(null);
 44	  const agentRef = useRef(null);
 45	  const photoUrls = useRef([]);
 46	  const onTriageRef = useRef(onTriage);
 47	  onTriageRef.current = onTriage;
 48	
 49	  const mic = useUserMedia({ enabled: VOICE_WANTS_AUDIO && consent && micOn, audio: true });
 50	  const cam = useUserMedia({ enabled: camOn, video: true, facing });
 51	  // Recording = the mic is open and the agent is taking it in. The meter shows the owner it hears them.
 52	  const recording = VOICE_WANTS_AUDIO && micOn && !!mic.stream && listening;
 53	  const level = useMicLevel(recording ? mic.stream : null);
 54	  const hearing = recording && level >= 0.15;
 55	
 56	  // ---- the conversation with Pawse
 57	  useEffect(() => {
 58	    if (IS_LIVE_VOICE && !consent) return;
 59	    const agent = createVoiceAgent({ lang, shareWithGemini: consent });
 60	    agentRef.current = agent;
 61	    const off = agent.on((e) => {
 62	      switch (e.type) {
 63	        case 'transcript':
 64	          if (e.role === 'ai') setAiLine(e.text);
 65	          else {
 66	            setUserLine(e.text);
 67	            setUserPartial(!!e.partial);
 68	          }
 69	          break;
 70	        case 'transcribing':
 71	          setTranscribing(e.on);
 72	          break;
 73	        case 'speaking':
 74	          setSpeaking(e.who);
 75	          break;
 76	        case 'listening':
 77	          setListening(e.on);
 78	          break;
 79	        case 'suggestions':
 80	          setChips(e.items || []);
 81	          break;
 82	        case 'image_received':
 83	          setPhotos((p) => p.map((x, i) => (i === p.length - 1 ? { ...x, received: true } : x)));
 84	          break;
 85	        case 'tool_result': setToolResults(p => [...p.slice(-4), e]); break;
 86	        case 'agents': setTrace(e.trace); break;
 87	        case 'triage': {
 88	          const problems = validateTriage(e);
 89	          if (problems.length) console.warn('[Pawse] triage violates the contract:', problems, e);
 90	          onTriageRef.current(e);
 91	          setSheetOpen(true);
 92	          break;
 93	        }
 94	        case 'error':
 95	          setError(e.message || '');
 96	          break;
 97	        default:
 98	          break;
 99	      }
100	    });
101	    agent.setMicMuted(!micOn);
102	    agent.setOutputMuted?.(!soundOn);
103	    agent.start();
104	    return () => {
105	      off();
106	      agent.end();
107	    };
108	  }, [lang, consent]);
109	
110	  // ---- which AI runs this call (model ids come from the backend, never hardcoded)
111	  useEffect(() => {
112	    let alive = true;
113	    if (IS_LIVE_VOICE) loadCapabilities(VOICE_AGENT_URL || '').then((c) => alive && setCaps(c));
114	    const refresh = () => setBrowser(resolveVoiceName(lang));
115	    refresh();
116	    const off = onVoicesChanged(refresh);
117	    return () => {
118	      alive = false;
119	      off();
120	    };
121	  }, [lang]);
122	
