241	              <button type="button" className="cam-tool" onClick={() => setCamOn(false)} aria-label={t.closeCamera}>
242	                <Icon name="x" size={18} />
243	              </button>
244	            </div>
245	          </div>
246	        ) : (
247	          <div className={`avatar-stage ${speaking === 'ai' ? 'talking' : ''} ${listening ? 'listening' : ''} ${hearing ? 'hearing' : ''}`}>
248	            {recording && <span className="mic-ring" style={{ transform: `scale(${0.88 + level * 0.17})`, opacity: 0.35 + level * 0.65 }} aria-hidden="true" />}
249	            <span className="halo h1" aria-hidden="true" />
250	            <span className="halo h2" aria-hidden="true" />
251	            <Avatar size={168} speaking={speaking === 'ai'} listening={listening} />
252	          </div>
253	        )}
254	        <p className="stage-name">Pawse</p>
255	        <ProviderChips t={t} items={voiceCallProviders({ path: VOICE_PATH, caps, browser, muted: !soundOn })} />
256	        <p className="stage-status" aria-live="polite">
257	          {transcribing ? (
258	            <span className="listening-label">
259	              <span className="dots" aria-hidden="true">
260	                <i />
261	                <i />
262	                <i />
263	              </span>
264	              {t.transcribing}
265	            </span>
266	          ) : recording ? (
267	            <span className={`rec-label ${hearing ? 'hot' : ''}`}>
268	              <span className="rec-dot" aria-hidden="true" />
269	              {hearing ? t.hearing : t.recording}
270	              <span className="level-bars" aria-hidden="true">
271	                {bars.map((w, i) => (
272	                  <i key={i} style={{ transform: `scaleY(${0.15 + Math.min(1, level * w * 1.3) * 0.85})` }} />
273	                ))}
274	              </span>
275	            </span>
276	          ) : needsMic ? (
277	            <span className="listening-label">{t.tapMic}</span>
278	          ) : listening ? (
279	            <span className="listening-label">
280	              <span className="dots" aria-hidden="true">
281	                <i />
282	                <i />
283	                <i />
284	              </span>
285	              {t.listening}
286	            </span>
287	          ) : (
288	            status
289	          )}
290	        </p>
291	      </section>
292	
293	      {!sheetVisible && (
294	        <div className="vcall-bottom">
295	          <div className="captions" aria-live="polite">
296	            {userLine && <p className={userPartial ? 'cap-user partial' : 'cap-user'}>{userLine}</p>}
297	            {transcribing ? (
298	              <p className="cap-user partial">{t.transcribing}</p>
299	            ) : (
300	              hearing &&
301	              !userPartial && (
302	                <p className="cap-user partial waiting" aria-label={t.hearing}>
303	                  <span className="dots light" aria-hidden="true">
304	                    <i />
305	                    <i />
306	                    <i />
307	                  </span>
308	                </p>
309	              )
310	            )}
311	            {lastPhoto && (
312	              <div className="cap-photo">
313	                <img src={lastPhoto.url} alt={t.photoSent} />
314	                <span>{lastPhoto.received ? `✓ ${t.photoSent}` : '…'}</span>
315	              </div>
316	            )}
317	            {aiLine && <p className="cap-ai">{aiLine}</p>}
318	            {error && <p className="cap-error">{error}</p>}
319	            {VOICE_WANTS_AUDIO && mic.error && <p className="cap-error">{t.micUnavailable}</p>}
320	          </div>
321	
322	          {chips.length > 0 && (
323	            <div className="kw-chips" role="group" aria-label="Suggestions">
324	              {chips.map((c) => (
325	                <button key={c} type="button" className="kw-chip" onClick={() => send(c)}>
326	                  {c}
327	                </button>
328	              ))}
329	            </div>
330	          )}
331	
332	          <form
333	            className="type-bar"
334	            onSubmit={(e) => {
335	              e.preventDefault();
336	              send(draft);
337	            }}
338	          >
339	            <button type="button" className="type-icon" onClick={() => fileRef.current && fileRef.current.click()} aria-label={t.photo} title={t.photo}>
340	              <Icon name="camera" size={20} />
341	            </button>
342	            <input
343	              disabled={IS_LIVE_VOICE && !consent}
344	              maxLength={4000}
345	              value={draft}
346	              onChange={(e) => setDraft(e.target.value)}
347	              placeholder={t.typePlaceholder}
348	              aria-label={t.typePlaceholder}
349	              enterKeyHint="send"
350	            />
351	            <button type="submit" className="type-send" aria-label={t.send} disabled={!draft.trim()}>
352	              <Icon name="send" size={18} />
353	            </button>
354	          </form>
355	          <input ref={fileRef} type="file" accept="image/*" capture="environment" hidden onChange={onPhoto} />
356	
357	          <nav className="call-controls" aria-label="Call controls">
358	            <button
359	              type="button"
360	              className={`ctl ${!micOn ? 'off' : ''} ${recording ? 'rec' : ''} ${needsMic ? 'nudge' : ''}`}
361	              style={recording ? { '--level': level } : undefined}
362	              onClick={toggleMic}
363	              aria-pressed={!micOn}
364	              aria-label={t.mic}
365	            >
366	              <Icon name={micOn ? 'mic' : 'micOff'} size={26} />
367	            </button>
368	            <button type="button" className="ctl hang" onClick={onEnd} aria-label={t.hangup}>
369	              <Icon name="phone" size={28} style={{ transform: 'rotate(135deg)' }} />
370	            </button>
371	            <button type="button" className={camOn ? 'ctl on' : 'ctl'} onClick={() => setCamOn((v) => !v)} aria-pressed={camOn} aria-label={t.camera}>
372	              <Icon name={camOn ? 'video' : 'videoOff'} size={26} />
373	            </button>
374	          </nav>
375	        </div>
376	      )}
377	
378	      {triage && !sheetOpen && (
379	        <button type="button" className="reopen" onClick={() => setSheetOpen(true)}>
380	          <Icon name="chevronUp" size={18} /> {t.viewAdvice}
381	        </button>
382	      )}
383	
384	      {sheetVisible && (
385	        <div className="sheet" role="dialog" aria-label={t.adviceTitle}>
386	          <div className="sheet-grab" aria-hidden="true" />
387	          <PlanPanel t={t} triage={triage} vet={vet} insurance={insurance} onCall={onCall} />
388	          <div className="sheet-foot">
389	            <button type="button" className="btn ghost" onClick={() => setSheetOpen(false)}>
390	              {t.keepTalking}
391	            </button>
392	            <button type="button" className="btn soft" onClick={onEnd}>
393	              {t.done}
394	            </button>
395	          </div>
396	        </div>
397	      )}
398	    </main>
399	  );
400	}

