  1	import { useEffect, useRef, useState } from 'react';
  2	import { draftHandoff, searchDemoPolicy, generateSpeech } from '../agents/handoff.js';
  3	import ProviderChips from '../components/ProviderChips.jsx';
  4	import { loadCapabilities, handoffProviders } from '../agents/providers.js';
  5	import { PHONE_AGENT_URL } from '../config.js';
  6	
  7	export default function LiveHandoff({ t, lang, target, clinic, context, onDone, onRehearse }) {
  8	  const [message, setMessage] = useState(context.summary || '');
  9	  const [consent, setConsent] = useState(false);
 10	  const [gradiumConsent, setGradiumConsent] = useState(false);
 11	  const [voice, setVoice] = useState('my_voice');
 12	  const [script, setScript] = useState(null);
 13	  const [evidence, setEvidence] = useState(null);
 14	  const [query, setQuery] = useState('accident deductible home visit');
 15	  const [audio, setAudio] = useState('');
 16	  const [error, setError] = useState('');
 17	  const [busy, setBusy] = useState(false);
 18	  const [caps, setCaps] = useState(null);
 19	  const pending = useRef(null);
 20	  useEffect(() => { let alive = true; loadCapabilities(PHONE_AGENT_URL || '').then(c => alive && setCaps(c)); return () => { alive = false; }; }, []);
 21	  const audioRef = useRef('');
 22	  useEffect(() => () => { pending.current?.abort(); if (audioRef.current) URL.revokeObjectURL(audioRef.current); }, []);
 23	  async function run(task) {
 24	    if (pending.current) return;
 25	    const controller = new AbortController(); pending.current = controller;
 26	    const timer = setTimeout(() => controller.abort(), 65000);
 27	    setBusy(true); setError('');
 28	    try { await task(controller.signal); }
 29	    catch (e) { if (!controller.signal.aborted) setError(e.message); else setError('Request stopped or timed out. Retry explicitly.'); }
 30	    finally { clearTimeout(timer); pending.current = null; setBusy(false); }
 31	  }
 32	  function clearAudio() {
 33	    if (audioRef.current) URL.revokeObjectURL(audioRef.current);
 34	    audioRef.current = ''; setAudio('');
 35	  }
 36	  const callUrl = /^tel:\+[1-9]\d{6,14}$/.test(clinic?.callUrl || '') ? clinic.callUrl : null;
 37	  return <main className="plan handoff">
 38	    <h1>Prepare {target === 'insurance' ? 'insurer' : 'vet'} conversation</h1>
 39	    <ProviderChips t={t} items={handoffProviders({ caps, voice, audioReady: !!audio, target })} />
 40	    <p className="note">No call has been placed. No appointment or insurance coverage has been confirmed.</p>
 41	    {clinic && <p>{clinic.name} · {clinic.phone || 'No published phone available'}</p>}
 42	    <section className="card">
 43	      <label>Facts and questions to include<textarea aria-label="Facts and questions" value={message} maxLength={4000} onChange={e => { setMessage(e.target.value); setScript(null); clearAudio(); }} /></label>
 44	      <label><input type="checkbox" checked={consent} onChange={e => setConsent(e.target.checked)} /> Share these facts with Gemini to draft a German script with subtitles.</label>
 45	      <button className="btn primary" disabled={busy || !consent || !message.trim()} onClick={() => run(async signal => { clearAudio(); setScript(null); setScript(await draftHandoff(message, lang, target, consent, signal)); })}>Generate German draft</button>
 46	    </section>
 47	    {script && <section className="card">
 48	      <h2>Review before using</h2>
 49	      {script.lines.map((line,i) => <div key={i}><p lang="de">{line.german}</p><p>{line.subtitle}</p></div>)}
 50	      <label>Speech voice <select value={voice} onChange={e => {setVoice(e.target.value); clearAudio();}}><option value="my_voice">My approved voice</option><option value="standard">Standard German voice</option></select></label>
 51	      <p>Your saved German voice is reused automatically in local mode. Set it up once from “My voice” on the home screen; no new clone is needed for each emergency.</p>
 52	      <label><input type="checkbox" checked={gradiumConsent} onChange={e => setGradiumConsent(e.target.checked)} /> I reviewed the script and agree to share it with Gradium using the selected voice.</label>
 53	      <button className="btn primary" disabled={busy || !gradiumConsent} onClick={() => run(async signal => { clearAudio(); const blob = await generateSpeech(script.lines.map(x=>x.german).join('\n'),voice,gradiumConsent,signal); audioRef.current = URL.createObjectURL(blob); setAudio(audioRef.current); })}>Generate reviewed audio</button>
 54	      {audio && <><audio controls src={audio} /><a href={audio} download="pawse-reviewed-script.wav">Download audio</a></>}
 55	    </section>}
 56	    {target === 'insurance' && <section className="card">
 57	      <h2>Demo policy evidence — not your personal coverage</h2>
 58	      <p>English lexical search over the demo policy only. Personal policy upload is not connected.</p>
 59	      <input aria-label="Demo policy question in English" value={query} maxLength={1000} onChange={e => setQuery(e.target.value)} />
 60	      <button className="btn soft" disabled={busy || !query.trim()} onClick={() => run(async signal => setEvidence(await searchDemoPolicy(query,signal)))}>Search demo evidence</button>
 61	      {evidence && <><p>{evidence.status} · Insurance approval: {evidence.insurance_approval}</p>{evidence.evidence.map(e => <article key={e.evidence_id}><h3>{e.title} · {e.section}</h3><p style={{whiteSpace:'pre-wrap'}}>{e.snippet}</p><small>{e.source_id} · {e.source_sha256}</small></article>)}</>}
 62	    </section>}
 63	    {callUrl && <section className="card"><p>Open your device dialer for {clinic.name}. Pawse cannot join or speak into this call.</p><a className="btn soft" href={callUrl}>Open dialer: {clinic.phone}</a></section>}
 64	    {busy && <p role="status">Preparing…</p>}{error && <p role="alert">{error}</p>}
 65	    {onRehearse && <button className="btn soft" onClick={onRehearse}>Open simulated Mimi phone rehearsal</button>}
 66	    <button className="btn ghost" onClick={() => onDone(null)}>Back to care summary</button>
 67	  </main>;
 68	}
 69	import { useEffect, useRef, useState } from 'react';
 70	import { blobToWavBase64 } from '../agents/liveVoiceAgent.js';
 71	import { prepareGermanPreview } from '../agents/ownVoice.js';
 72	import { generateSpeech } from '../agents/handoff.js';
 73	
 74	const EMERGENCY_TEST = 'Dies ist eine Übung, kein echter Notruf. Guten Tag, hier spricht die KI-Assistenz im Auftrag der Katzenhalterin oder des Katzenhalters. Meine Katze Mimi hinkt nach einem Sprung. Können wir sie heute untersuchen lassen? Bitte bestätigen Sie die Adresse und ob Sie Katzen behandeln.';
 75	export default function OwnVoice({onBack}) {
 76	  const [profile,setProfile]=useState({}),[language,setLanguage]=useState('en'),[consent,setConsent]=useState(false);
 77	  const [recording,setRecording]=useState(false),[busy,setBusy]=useState(false),[error,setError]=useState('');
 78	  const [sample,setSample]=useState(null),[sampleUrl,setSampleUrl]=useState(''),[preview,setPreview]=useState(''),[result,setResult]=useState('');
 79	  const [stage,setStage]=useState('');
 80	  const [heard,setHeard]=useState(false),[approved,setApproved]=useState(false);
 81	  const resources=useRef({stream:null,recorder:null,timer:null,urls:[],controller:null,alive:true});
 82	  const makeUrl=blob=>{if(!resources.current.alive)return '';const u=URL.createObjectURL(blob);resources.current.urls.push(u);return u;};
 83	  async function api(path, body, binary=false, signal){
 84	    const r=await fetch(`/api/v1/voice/${path}`,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined,signal});
 85	    if(!r.ok){const j=await r.json().catch(()=>({}));throw Error(typeof j.detail==='string'?j.detail:`Voice request failed (${r.status})`);}
 86	    return binary?r.blob():r.json();
 87	  }
 88	  useEffect(()=>{
 89	    resources.current.alive=true;
 90	    const ctl=new AbortController();api('status',null,false,ctl.signal).then(setProfile).catch(()=>{});
 91	    return ()=>{ctl.abort();const r=resources.current;r.alive=false;clearTimeout(r.timer);r.controller?.abort();if(r.recorder?.state==='recording')r.recorder.stop();r.stream?.getTracks().forEach(t=>t.stop());r.urls.forEach(URL.revokeObjectURL);};
 92	  },[]);
 93	  async function task(fn){
 94	    if(resources.current.controller||recording)return;
 95	    const ctl=new AbortController();resources.current.controller=ctl;const timer=setTimeout(()=>ctl.abort(),240000);
 96	    setBusy(true);setError('');
 97	    try{await fn(ctl.signal);}catch(e){if(resources.current.alive)setError(e.name==='AbortError'?'Request timed out. Your voice may already be saved. Use Refresh voice status before retrying.':e.message);}
 98	    finally{clearTimeout(timer);resources.current.controller=null;if(resources.current.alive)setBusy(false);}
 99	  }
100	  async function prepare(signal){
101	    setHeard(false);setApproved(false);
102	    const blob=await prepareGermanPreview({api,profile,sample,language,signal,onProfile:setProfile,onStage:setStage});
103	    if(resources.current.alive)setPreview(makeUrl(blob));
104	  }
105	  async function record(){
106	    if(busy||recording)return;
107	    // A missing recorder is a browser limit, not a refused permission: say which one it is.
108	    if(typeof MediaRecorder==='undefined'||!navigator.mediaDevices?.getUserMedia){setError('This browser cannot record audio here. Use a current Chrome, Edge, Firefox or Safari (14.1 or newer).');return;}
109	    setBusy(true);setError('');setSample(null);setSampleUrl('');
110	    try{
111	      const stream=await navigator.mediaDevices.getUserMedia({audio:true});
112	      if(!resources.current.alive){stream.getTracks().forEach(t=>t.stop());return;}
113	      resources.current.stream=stream;
114	      const rec=new MediaRecorder(stream), chunks=[];resources.current.recorder=rec;
115	      rec.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};
116	      rec.onstop=async()=>{
117	        clearTimeout(resources.current.timer);stream.getTracks().forEach(t=>t.stop());
118	        if(!resources.current.alive)return;
119	        setRecording(false);setBusy(true);
120	        try{
121	          const data=await blobToWavBase64(new Blob(chunks,{type:rec.mimeType}));
122	          if(!data)throw Error('Recording too short. Read the sample for 10–25 seconds.');
123	          const bytes=Uint8Array.from(atob(data),c=>c.charCodeAt(0));const duration=(bytes.length-44)/32000;
124	          if(duration<10||duration>30)throw Error('Record 10–30 seconds. Try again at a natural pace.');
125	          if(resources.current.alive){setSample(data);setSampleUrl(makeUrl(new Blob([bytes],{type:'audio/wav'})));}
126	        }catch(e){if(resources.current.alive)setError(e.message);}finally{if(resources.current.alive)setBusy(false);}
127	      };
128	      rec.start();setRecording(true);setBusy(false);resources.current.timer=setTimeout(()=>{if(rec.state==='recording')rec.stop();},25000);
129	    }catch(e){resources.current.stream?.getTracks().forEach(t=>t.stop());setBusy(false);setError('Microphone unavailable. Allow recording in your browser and try again.');}
130	  }
131	  return <main className="plan handoff">
132	    <h1>My voice · emergency rehearsal</h1>
133	    <p>{profile.voice_saved ? "Use your saved German voice for the emergency rehearsal below." : "Record your own voice for 10–25 seconds. Nothing is sent until you confirm cloning."} This rehearsal does not call a clinic.</p>
134	    <p>{profile.gradium_configured?'Gradium configured':'Gradium key missing: local recording and playback work; cloning needs GRADIUM_API_KEY on the server.'}</p>
135	    {(stage||busy)&&<p role="status">{stage||'Working…'}</p>}
136	    {error&&<p role="alert">{error}</p>}
137	    <button className="btn ghost" disabled={busy||recording} onClick={()=>task(async signal=>{setProfile(await api('status',null,false,signal));setStage('Voice status refreshed.');})}>Refresh voice status</button>
138	    <section className="card">
139	      {profile.voice_saved&&<p role="status">Your approved German voice is saved on this device. No new recording or clone is needed. Scroll down to the emergency rehearsal.</p>}
140	      {!profile.voice_saved&&<><label>Recording language<select disabled={busy||recording} value={language} onChange={e=>{setLanguage(e.target.value);setSample(null);setSampleUrl('');}}><option value="en">English</option><option value="de">German</option></select></label>
141	      <p>{language==='en'?'Hello, I am recording my own voice for Pawse. My cat is very important to me. I want to explain calmly to the veterinary practice what happened, ask whether they can see her today, and understand every next step. Please include me in every decision.':'Hallo, ich nehme meine eigene Stimme für Pawse auf. Meine Katze ist mir sehr wichtig. Ich möchte der Tierarztpraxis ruhig erklären, was passiert ist, und alle nächsten Schritte verstehen. Bitte beziehen Sie mich bei jeder Entscheidung mit ein.'}</p>
142	      <button className="btn primary" disabled={busy} onClick={()=>recording?resources.current.recorder.stop():record()}>{recording?'Stop recording':'Record my voice'}</button>
143	      {sampleUrl&&<audio controls src={sampleUrl}/>}</> }
144	      <label><input type="checkbox" checked={consent} onChange={e=>setConsent(e.target.checked)}/> {profile.voice_saved ? "I agree to send the rehearsal text to Gradium using my saved German voice." : "This is my own voice. I agree to send this recording to Gradium to create and preview my voice."}</label>
145	      {!profile.voice_saved&&<button className="btn soft" disabled={busy||recording||!sample||!consent||!profile.gradium_configured||!!profile.source_id} onClick={()=>task(prepare)}>Clone and preview in German</button>}
146	    </section>
147	    {profile.source_id&&!profile.voice_saved&&<section className="card">
148	      <h2>German voice preview</h2>
149	      <p>Source clone saved in your Gradium voice library: <code>{profile.source_id}</code></p>
150	      <p>{profile.german_voice_id?`Saved German voice: ${profile.german_voice_id}`:'German candidate is not saved as a permanent voice yet.'}</p>
151	      <button className="btn primary" disabled={busy||recording||!consent} onClick={()=>task(prepare)}>Continue to German preview</button>
152	      {!profile.german_voice_id&&!profile.candidate_pending&&<button className="btn soft" disabled={busy||recording||!consent} onClick={()=>task(async signal=>setProfile(await api('localizations',{share_with_gradium:true},false,signal)))}>Create German version</button>}
153	      {profile.candidate_pending&&!profile.candidate_ready&&<button className="btn soft" disabled={busy||recording} onClick={()=>task(async signal=>setProfile(await api('localizations/current',null,false,signal)))}>Check readiness</button>}
154	      <button className="btn soft" disabled={busy||recording||!consent||!(profile.german_voice_id||profile.candidate_ready)} onClick={()=>task(async signal=>{setHeard(false);setApproved(false);setPreview(makeUrl(await api('preview',{share_with_gradium:true},true,signal)));})}>Generate preview</button>
155	      {preview&&<audio controls src={preview} onEnded={()=>setHeard(true)}/>}
156	      <label><input type="checkbox" disabled={!heard} checked={approved} onChange={e=>setApproved(e.target.checked)}/> I listened to the preview and approve this voice for the test below.</label>
157	      {(profile.candidate_ready||profile.german_voice_id)&&!profile.voice_saved&&<button className="btn soft" disabled={busy||recording||!approved||!consent} onClick={()=>task(async signal=>setProfile(await api('localizations/current/save',{share_with_gradium:true,listened_to_preview:true},false,signal)))}>Save approved voice</button>}
158	    </section>}
159	    <section className="card"><h2>Emergency scenario · test only</h2><p lang="de">{EMERGENCY_TEST}</p>
160	      <p>English: This is a rehearsal, not a real emergency call. Mimi is limping after a jump. Can she be examined today? Please confirm the address and that the practice treats cats.</p>
161	      <button className="btn primary" disabled={busy||recording||!consent||!(approved||profile.voice_saved)||!profile.my_voice_ready} onClick={()=>task(async signal=>setResult(makeUrl(await generateSpeech(EMERGENCY_TEST,'my_voice',consent,signal))))}>Speak the rehearsal in my voice</button>
162	      {result&&<><audio controls src={result}/><a href={result} download="pawse-own-voice-rehearsal.wav">Download rehearsal</a></>}
163	    </section>
164	    <button className="btn ghost" onClick={onBack}>Back</button>
165	  </main>;
166	}
167	import { useEffect, useState } from 'react';
168	
169	/**
170	 * Opens the camera and/or microphone while `enabled`.
171	 * Returns { stream, error } – error is set when the device can't be opened
172	 * (no device, permission denied, or plain http on a phone).
173	 */
174	export default function useUserMedia({ enabled = true, video = false, audio = false, facing = 'environment' } = {}) {
175	  const [stream, setStream] = useState(null);
176	  const [error, setError] = useState(null);
177	
178	  useEffect(() => {
179	    if (!enabled || (!video && !audio)) {
180	      setStream(null);
181	      setError(null);
182	      return undefined;
183	    }
184	    const md = typeof navigator !== 'undefined' ? navigator.mediaDevices : null;
185	    if (!md || !md.getUserMedia) {
186	      setError('unsupported');
187	      return undefined;
188	    }
189	
190	    let cancelled = false;
191	    let current = null;
192	    setError(null);
193	    md.getUserMedia({ video: video ? { facingMode: { ideal: facing } } : false, audio })
194	      .then((s) => {
195	        if (cancelled) {
196	          s.getTracks().forEach((tr) => tr.stop());
197	          return;
198	        }
199	        current = s;
200	        setStream(s);
201	      })
