  1	// Live phone agent for Pawse. There is NO telephony: the German script and the numbers come from
  2	// the backend (GET /api/v1/demo/mimi), every AI line is spoken with the same Gradium German voice
  3	// (POST /api/v1/voice/speech, only with explicit consent), and every callee reply and the result
  4	// stay marked `simulated: true`. Nothing is ever dialled or booked. Implements ../contracts.js.
  5	//
  6	// One call = one server-issued call id: the first AI line carries the AI disclosure and the server
  7	// answers with an X-Pawse-Call-Id header; later lines send that id so the server does not repeat
  8	// the disclosure. If Gradium fails (no key, 503, network), the rest of the call uses browser speech
  9	// so the voice never flips back and forth.
 10	
 11	import { PHONE_AGENT_URL } from '../config.js';
 12	import { speak, stopSpeech, isSpeechMuted, resolveVoiceName } from './speech.js';
 13	import { phoneVoiceEvent } from './providers.js';
 14	
 15	// Must equal DISCLOSURE in pawse/voice.py so the server does not prepend a second greeting.
 16	const DISCLOSURE = 'Guten Tag, hier ist Pawse, die KI-Assistenz im Auftrag der Katzenhalterin oder des Katzenhalters.';
 17	const FIRST_LINE = {
 18	  original: `${DISCLOSURE} Ich bin ein KI-Assistent und kein Mensch.`,
