 35	/**
 36	 * Fetches Gradium audio for the AI lines of one call, strictly in order (the first response
 37	 * carries the call id the later ones need). Each line is fetched at most once, so the page can
 38	 * preload the next AI line while the current one plays.
 39	 */
 40	function createGradiumLines(base, voice, state) {
 41	  const cache = new Map();
 42	  let chain = Promise.resolve();
 43	  let callId = null;
 44	  let failed = false;
 45	
 46	  const request = async (text) => {
 47	    if (failed || state.ended) return null;
 48	    try {
 49	      const res = await fetch(`${base}/api/v1/voice/speech`, {
 50	        method: 'POST',
 51	        headers: { 'Content-Type': 'application/json' },
 52	        body: JSON.stringify({ text, language: 'de', voice, share_with_gradium: true, ...(callId ? { call_id: callId } : {}) }),
 53	      });
 54	      if (!res.ok) throw new Error(`speech ${res.status}`);
 55	      const id = res.headers && typeof res.headers.get === 'function' ? res.headers.get('x-pawse-call-id') : null;
 56	      if (id) callId = id;
 57	      return await res.blob();
 58	    } catch {
 59	      failed = true; // stay on browser speech for the rest of this call
 60	      return null;
 61	    }
 62	  };
 63	
 64	  return {
 65	    get failed() {
 66	      return failed;
 67	    },
 68	    /** Promise<Blob|null> for line `key`; queued behind every earlier request. */
 69	    fetch(key, text) {
 70	      if (!cache.has(key)) {
 71	        const p = chain.then(() => request(text));
 72	        chain = p;
 73	        cache.set(key, p);
 74	      }
 75	      return cache.get(key);
 76	    },
 77	  };
 78	}
