 80	/** Plays one audio blob. Resolves true if it played to the end, false to fall back. */
 81	function playBlob(blob, state) {
 82	  if (!blob || state.ended || typeof Audio === 'undefined' || typeof URL === 'undefined' || !URL.createObjectURL) {
 83	    return Promise.resolve(false);
 84	  }
 85	  return new Promise((resolve) => {
 86	    let url;
 87	    try {
 88	      url = URL.createObjectURL(blob);
 89	    } catch {
 90	      resolve(false);
 91	      return;
 92	    }
 93	    const a = new Audio(url);
 94	    state.audio = a;
 95	    const done = (ok) => {
 96	      if (state.audio === a) state.audio = null;
 97	      try { URL.revokeObjectURL(url); } catch { /* ignore */ }
 98	      resolve(ok);
 99	    };
100	    a.onended = () => done(true);
101	    a.onerror = () => done(false);
102	    try {
103	      const p = a.play();
104	      if (p && p.catch) p.catch(() => done(false));
105	    } catch {
106	      done(false);
107	    }
108	  });
109	}
