186	  // Gradium audio only with explicit consent from the page (context.gradiumConsent === true);
187	  // the page may withdraw or give it mid-call with setGradiumConsent().
188	  const voice = context.voice === 'my_voice' ? 'my_voice' : 'standard';
189	  let gradiumConsent = context.gradiumConsent === true;
190	  const gradium = createGradiumLines(base, voice, state);
191	  const useGradium = () => gradiumConsent && !gradium.failed && !isSpeechMuted() && typeof fetch === 'function';
192	
193	  // Tell the page which voice Pawse really uses; only emits when it changes (e.g. Gradium fails -> browser).
194	  let lastVoice = '';
195	  const announceVoice = (gradiumOk) => {
196	    const ev = phoneVoiceEvent({ gradiumOk, muted: isSpeechMuted(), variant: voice, browser: resolveVoiceName('de') });
197	    const sig = JSON.stringify(ev);
198	    if (sig !== lastVoice) {
199	      lastVoice = sig;
200	      emit(ev);
201	    }
202	  };
203	
204	  async function say(lines, i) {
205	    const line = lines[i];
206	    if (line.who === 'ai' && !useGradium()) announceVoice(false);
207	    if (line.who === 'ai' && useGradium()) {
208	      const blob = await gradium.fetch(i, line.original);
209	      // Preload the next AI line while this one plays.
210	      const next = lines.findIndex((l, j) => j > i && l.who === 'ai');
211	      if (next >= 0 && useGradium()) gradium.fetch(next, lines[next].original);
212	      if (state.ended) return;
213	      announceVoice(!!blob);
214	      if (await playBlob(blob, state)) return;
215	      announceVoice(false); // Gradium failed or was not playable: the browser voice speaks this line
216	    }
217	    if (state.ended) return;
218	    await speak(line.original, 'de', { speed, pitch: line.who === 'callee' ? 0.8 : 1.15 });
219	  }
220	
221	  async function run() {
222	    emit({ type: 'status', state: 'dialing' });
223	    let story;
224	    try {
225	      story = await fetchStory(base);
226	    } catch (err) {
227	      emit({ type: 'error', message: `Phone agent: ${err.message}` });
228	      finish();
229	      return;
230	    }
231	    await wait(1500);
232	    if (state.ended) return;
233	    emit({ type: 'status', state: 'connected' });
234	    announceVoice(useGradium());
235	
236	    const step = (story.steps || [])[STEP_INDEX[target] ?? 2] || { lines: [] };
237	    const lines = [
238	      { who: 'ai', original: FIRST_LINE.original, text: FIRST_LINE.text[lang] ?? FIRST_LINE.text.en },
239	      ...(step.lines || []).map((l) => ({
240	        who: /^pawse/i.test(l.speaker) ? 'ai' : 'callee',
241	        original: l.german,
242	        // The backend subtitles are English; the zh UI shows them as is rather than inventing a translation.
243	        text: l.subtitle,
244	      })),
245	    ];
246	    for (const [i, line] of lines.entries()) {
247	      await wait(450);
248	      if (state.ended) return;
249	      emit({ type: 'speaking', who: line.who });
250	      const ev = { type: 'line', who: line.who, original: line.original, text: line.text };
251	      if (line.who === 'callee') ev.simulated = true;
252	      emit(ev);
253	      await say(lines, i);
254	      if (state.ended) return;
255	      emit({ type: 'speaking', who: 'none' });
256	    }
257	    await wait(500);
258	    if (state.ended) return;
259	    emit({ type: 'result', ...(target === 'insurance' ? buildInsuranceResult(story, lang) : buildVetResult(story, lang, context)) });
