524	      </section>
525	
526	      <section className="pc-lines" aria-live="polite">
527	        <h2 className="pc-sub">
528	          {t.progressTitle} <span className="pc-sub-note">{t.progressNote}</span>
529	        </h2>
530	        <ol className="steps">
531	          {status === 'dialing' && <li className="step now">{t.dialing}</li>}
532	          {steps.map((s, i) =>
533	            s.chose ? (
534	              <li key={i} className="step done you">
535	                {t.youChose}: <strong>{s.chose}</strong>
536	              </li>
537	            ) : (
538	              <li key={i} className={`step ${live && i === steps.length - 1 && !question ? 'now' : 'done'}`}>
539	                {s.text}
540	              </li>
541	            )
542	          )}
543	        </ol>
544	
545	        {question && (
546	          <div className="ask-card" role="group" aria-label={t.questionTitle}>
547	            <h3>{t.questionTitle}</h3>
548	            <p>{question.text}</p>
549	            <div className="ask-options">
550	              {question.options.map((o) => (
551	                <button key={o.id} type="button" className="btn primary" onClick={() => choose(o.id)}>
552	                  {o.label}
553	                </button>
554	              ))}
555	            </div>
556	            <p className="muted small">{t.holdNote}</p>
557	          </div>
558	        )}
559	
560	        {result && <ResultCard t={t} target={target} result={result} />}
561	        {result && <p className="translated-note">{t.resultNote}</p>}
562	        {error && <p className="pc-error">{error}</p>}
563	
564	        {lines.length > 0 && (
565	          <details className="transcript">
566	            <summary>{t.transcript}</summary>
567	            {lines.map((l, i) => (
568	              <div key={i} className={`line line-${l.who}`}>
569	                <span className="line-who">{l.who === 'ai' ? t.pawse : callee.name}</span>
570	                {l.simulated && <span className="sim-badge">{t.simulated}</span>}
571	                <p className="line-text">{l.text}</p>
572	                <p className="line-original" lang="de">{l.original}</p>
573	              </div>
574	            ))}
575	          </details>
576	        )}
577	      </section>
578	
579	      {gradium && listening && (
580	        <label className="pc-gradium">
581	          <input type="checkbox" checked={gradium.on} onChange={toggleGradium} />
582	          <span>
583	            <strong>{gradium.ownVoice ? t.gradiumOwnVoice : t.gradiumVoice}</strong>
584	            <span className="muted small">{t.gradiumNote}</span>
585	          </span>
586	        </label>
587	      )}
588	
589	      <footer className="pc-foot">
590	        {!live ? (
591	          <button type="button" className="btn primary wide" onClick={() => onDone(resultRef.current)}>
592	            {t.backToPawse}
593	          </button>
594	        ) : (
595	          <div className="pc-controls">
596	            <button
597	              type="button"
598	              className={`pc-listen ${listening ? 'on' : ''}`}
599	              onClick={toggleListen}
600	              aria-pressed={listening}
601	            >
602	              <span className="pc-ctl">
603	                <Icon name={listening ? 'volume' : 'volumeOff'} />
604	              </span>
605	              <span className="small">{listening ? t.listeningIn : t.listenIn}</span>
606	            </button>
607	            <button type="button" className="pc-ctl hang" onClick={hangup} aria-label={t.hangup}>
608	              <Icon name="phone" size={28} style={{ transform: 'rotate(135deg)' }} />
609	            </button>
610	            <span className="pc-ctl-spacer" />
611	          </div>
612	        )}
613	      </footer>
614	    </main>
615	  );
616	}

