 44	export function urgencyToLevel(urgency) {
 45	  return urgency === 'emergency' ? 'red' : 'yellow';
 46	}
 47	
 48	export function mapCareResult(res, lang = 'en') {
 49	  const t = T[lang] || T.en;
 50	  const a = (res && res.assessment) || {};
 51	  const level = urgencyToLevel(a.urgency);
 52	  const steps = [...(a.questions || []), ...(a.services_to_ask_about || [])].filter(Boolean);
 53	  if (!steps.length) steps.push(t.fallbackStep);
 54	  const out = {
 55	    type: 'triage',
 56	    level,
 57	    headline: t.headline[level],
 58	    steps,
 59	    summary: a.summary || (res && res.handoff) || t.headline[level],
 60	  };
 61	  if (level === 'red') out.escalation = a.summary || t.headline.red;
 62	  return out;
 63	}
