 65	function encodeWav(samples, rate) {
 66	  const buf = new ArrayBuffer(44 + samples.length * 2);
 67	  const v = new DataView(buf);
 68	  const w = (o, s) => [...s].forEach((c, i) => v.setUint8(o + i, c.charCodeAt(0)));
 69	  w(0, 'RIFF'); v.setUint32(4, 36 + samples.length * 2, true); w(8, 'WAVE'); w(12, 'fmt ');
 70	  v.setUint32(16, 16, true); v.setUint16(20, 1, true); v.setUint16(22, 1, true);
 71	  v.setUint32(24, rate, true); v.setUint32(28, rate * 2, true); v.setUint16(32, 2, true); v.setUint16(34, 16, true);
 72	  w(36, 'data'); v.setUint32(40, samples.length * 2, true);
 73	  for (let i = 0; i < samples.length; i++) {
 74	    const s = Math.max(-1, Math.min(1, samples[i]));
 75	    v.setInt16(44 + i * 2, s < 0 ? s * 0x8000 : s * 0x7fff, true);
 76	  }
 77	  return new Uint8Array(buf);
 78	}
 79	
 80	function toBase64(bytes) {
 81	  let s = '';
 82	  for (let i = 0; i < bytes.length; i += 0x8000) s += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
 83	  return btoa(s);
 84	}
 85	
 86	/** Recorded Blob (webm/mp4/...) -> base64 mono 16 kHz 16-bit WAV. Returns null if under 0.5 s. */
 87	export async function blobToWavBase64(blob) {
 88	  const AC = globalThis.AudioContext || globalThis.webkitAudioContext;
 89	  const ctx = new AC();
 90	  try {
 91	    const decoded = await ctx.decodeAudioData(await blob.arrayBuffer());
 92	    const rate = 16000;
 93	    const off = new OfflineAudioContext(1, Math.max(1, Math.ceil(decoded.duration * rate)), rate);
 94	    const src = off.createBufferSource();
 95	    src.buffer = decoded;
 96	    src.connect(off.destination);
 97	    src.start();
 98	    const rendered = await off.startRendering();
 99	    const pcm = rendered.getChannelData(0);
100	    if (pcm.length < rate * 0.5) return null;
101	    return toBase64(encodeWav(pcm.subarray(0, rate * 59), rate));
102	  } finally {
103	    try { ctx.close(); } catch { /* ignore */ }
104	  }
105	}
