107	function fileToBase64(file) {
108	  return new Promise((resolve, reject) => {
109	    const r = new FileReader();
110	    r.onload = () => resolve(String(r.result).split(',')[1] || '');
111	    r.onerror = () => reject(r.error);
112	    r.readAsDataURL(file);
113	  });
114	}
115	
116	export function createLiveVoiceAgent({ lang = 'en', shareWithGemini = false } = {}) {
117	  const t = T[lang] || T.en;
118	  const apiLang = ['en', 'zh', 'de', 'hi'].includes(lang) ? lang : 'en';
119	  const base = (VOICE_AGENT_URL || '').replace(/\/$/, '');
120	  const listeners = new Set();
121	  const userTurns = [];
122	  let started = false;
123	  let ended = false;
124	  let muted = false;
125	  let aiSpeaking = false;
126	  let photo = null; // { mime_type, data }
127	  let queue = Promise.resolve();
128	  let stream = null;
129	  let recorder = null;
130	  let chunks = [];
131	  let audioCtx = null;
132	  let poll = null;
133	  let heardMs = 0;
134	  let silentMs = 0;
135	  let turnMs = 0;
136	
137	  const emit = (e) => {
138	    if (ended && e.type !== 'ended') return;
139	    listeners.forEach((l) => {
140	      try { l(e); } catch { /* a bad listener must not break the call */ }
141	    });
142	  };
143	  const fail = (message) => emit({ type: 'error', message });
144	
145	  async function api(path, body) {
146	    if (ended || !shareWithGemini) throw new Error('Confirm sharing with Gemini before continuing.');
147	    const ctl = typeof AbortController !== 'undefined' ? new AbortController() : null;
148	    const timer = ctl && setTimeout(() => ctl.abort(), 60000);
149	    try {
150	      const res = await fetch(`${base}${path}`, {
151	        method: 'POST',
152	        headers: { 'Content-Type': 'application/json' },
153	        body: JSON.stringify(body),
154	        signal: ctl ? ctl.signal : undefined,
155	      });
156	      if (!res.ok) {
157	        let detail = '';
158	        try { const j = await res.json(); detail = typeof j.detail === 'string' ? j.detail : ''; } catch { /* ignore */ }
159	        throw new Error(detail || `HTTP ${res.status}`);
160	      }
161	      return await res.json();
162	    } finally {
163	      if (timer) clearTimeout(timer);
164	    }
165	  }
166	
167	  async function say(text) {
168	    if (ended) return;
169	    aiSpeaking = true;
170	    finishTurn(false);
171	    emit({ type: 'listening', on: false });
172	    emit({ type: 'speaking', who: 'ai' });
173	    emit({ type: 'transcript', role: 'ai', text });
174	    try { await speak(text, lang); } catch { /* speech is best effort */ }
175	    aiSpeaking = false;
176	    if (ended) return;
177	    emit({ type: 'speaking', who: 'none' });
178	    emit({ type: 'listening', on: !muted });
179	    resetTurn();
180	  }
181	
182	  async function advise() {
183	    const query = userTurns.join('\n');
184	    if (query.length > 4000) { fail('Conversation exceeds 4,000 characters. Start a new summary.'); return; }
185	    const body = { query, language: apiLang, share_with_ai: true };
186	    if (photo) body.photo = photo;
187	    let res;
188	    try {
189	      const run = await api('/api/v1/agents/runs', { care: body });
190	      res = run.care;
191	      emit({ type: 'agents', trace: run.trace || [], actions: run.actions || [] });
192	    } catch (err) {
193	      fail(`${t.errCare} (${err.message})`);
194	      emit({ type: 'listening', on: !muted });
195	      return;
196	    }
197	    if (ended) return;
198	    const triage = mapCareResult(res, lang);
199	    emit(triage);
200	    await say(triage.summary);
201	  }
202	
203	  const enqueue = (fn) => {
204	    queue = queue.then(fn).catch((err) => fail(String(err && err.message || err)));
205	    return queue;
206	  };
207	
208	  function takeUserText(text) {
209	    userTurns.push(text);
210	    emit({ type: 'speaking', who: 'user' });
211	    emit({ type: 'transcript', role: 'user', text });
212	    emit({ type: 'suggestions', items: [] });
213	    emit({ type: 'speaking', who: 'none' });
214	    return advise();
215	  }
216	
217	  async function transcribe(blob) {
218	    emit({ type: 'transcribing', on: true });
219	    try {
220	      await transcribeTurn(blob);
221	    } finally {
222	      emit({ type: 'transcribing', on: false });
223	    }
224	  }
225	
226	  async function transcribeTurn(blob) {
227	    let wav;
228	    try {
229	      wav = await blobToWavBase64(blob);
230	    } catch {
231	      fail(t.errTranscribe);
232	      return;
233	    }
234	    if (!wav || ended) return;
235	    let out;
236	    try {
237	      out = await api('/api/v1/voice/transcriptions', { audio: { data: wav }, language: apiLang, share_with_gemini: true });
238	    } catch (err) {
239	      fail(`${t.errTranscribe} (${err.message})`);
240	      return;
241	    }
242	    if (ended) return;
243	    const text = String((out && out.text) || '').trim();
244	    if (!text) { fail(t.noSpeech); return; }
245	    emit({ type: 'transcribing', on: false });
246	    await takeUserText(text);
247	  }
248	
249	  // --- recording with silence detection -----------------------------------------------------
250	  function resetTurn() {
251	    heardMs = 0; silentMs = 0; turnMs = 0;
252	    if (!recorder || recorder.state === 'inactive') startRecorder();
253	  }
254	
255	  function startRecorder() {
256	    if (!stream || ended || muted || aiSpeaking) return;
257	    chunks = [];
258	    heardMs = 0; silentMs = 0; turnMs = 0;
259	    try {
260	      recorder = new MediaRecorder(new MediaStream(stream.getAudioTracks()));
261	    } catch {
262	      fail(t.errMic);
263	      return;
264	    }
265	    const rec = recorder;
266	    rec.ondataavailable = (e) => { if (e.data && e.data.size) chunks.push(e.data); };
267	    rec.onstop = () => {
268	      const keep = rec.keepTurn;
269	      const blob = new Blob(chunks, { type: rec.mimeType || 'audio/webm' });
270	      chunks = [];
271	      if (keep && !ended) enqueue(() => transcribe(blob));
272	      if (!ended && recorder === rec) startRecorder();
273	    };
274	    rec.start();
275	  }
276	
277	  function finishTurn(keep) {
278	    if (!recorder || recorder.state !== 'recording') return;
279	    recorder.keepTurn = keep;
280	    emit({ type: 'speaking', who: 'none' });
281	    try { recorder.stop(); } catch { /* ignore */ }
282	  }
283	
284	  function tick(analyser, buf, step) {
285	    if (ended) return;
286	    if (muted || aiSpeaking) { heardMs = 0; silentMs = 0; turnMs = 0; return; }
287	    analyser.getFloatTimeDomainData(buf);
288	    let sum = 0;
289	    for (let i = 0; i < buf.length; i++) sum += buf[i] * buf[i];
290	    const loud = Math.sqrt(sum / buf.length) > SPEECH_RMS;
291	    if (loud) {
292	      if (heardMs === 0) emit({ type: 'speaking', who: 'user' });
293	      heardMs += step; silentMs = 0;
294	    } else if (heardMs > 0) {
295	      silentMs += step;
296	    }
297	    turnMs += step;
298	    if (heardMs >= MIN_SPEECH_MS && (silentMs >= SILENCE_MS || turnMs >= MAX_TURN_MS)) {
299	      finishTurn(true);
300	    } else if (heardMs === 0 && turnMs >= 10000) {
301	      finishTurn(false); // nothing said: recycle the recorder, discard
302	    } else if (heardMs > 0 && heardMs < MIN_SPEECH_MS && silentMs >= SILENCE_MS) {
303	      finishTurn(false); // a click or cough
304	    }
305	  }
306	
307	  function stopRecording() {
308	    if (poll) { clearInterval(poll); poll = null; }
309	    if (recorder) {
310	      recorder.keepTurn = false;
311	      try { if (recorder.state !== 'inactive') recorder.stop(); } catch { /* ignore */ }
312	      recorder = null;
313	    }
314	    try { audioCtx && audioCtx.close(); } catch { /* ignore */ }
315	    audioCtx = null;
316	  }
317	
318	  return {
319	    wantsAudio: true,
320	    on(cb) {
321	      listeners.add(cb);
322	      return () => listeners.delete(cb);
323	    },
324	    start() {
325	      if (started || ended) return;
326	      if (!shareWithGemini) { fail('Confirm sharing with Gemini before continuing.'); return; }
327	      started = true;
328	      enqueue(async () => {
329	        emit({ type: 'suggestions', items: t.chips });
330	        await say(t.greet);
331	        emit({ type: 'listening', on: !muted });
332	      });
333	    },
334	    end() {
335	      if (ended) return;
336	      stopRecording();
337	      stopSpeech();
338	      if (stream) { try { stream.getTracks().forEach((tr) => tr.stop()); } catch { /* ignore */ } }
339	      stream = null;
340	      ended = true;
341	      listeners.forEach((l) => { try { l({ type: 'ended' }); } catch { /* ignore */ } });
342	    },
343	    sendText(text) {
344	      const s = String(text || '').trim();
345	      if (!s || ended || !shareWithGemini) return;
346	      stopSpeech();
347	      aiSpeaking = false;
348	      enqueue(() => takeUserText(s));
349	    },
350	    async sendImage(file) {
351	      if (ended || !file || !shareWithGemini) return;
352	      if (file.size > 3000000) { fail('Use an image up to 3 MB.'); return; }
353	      const mime = file.type;
354	      if (!PHOTO_TYPES.includes(mime)) { fail(t.errPhoto); return; }
355	      try {
356	        photo = { mime_type: mime, data: await fileToBase64(file) };
357	      } catch {
358	        fail(t.errPhoto);
359	        return;
360	      }
361	      emit({ type: 'image_received' });
362	    },
363	    attachMedia({ audio } = {}) {
364	      if (!audio) { stopRecording(); stream = null; return; }
365	      if (ended || !shareWithGemini || audio === stream) return;
366	      stopRecording();
367	      stream = audio;
368	      const AC = globalThis.AudioContext || globalThis.webkitAudioContext;
369	      if (!AC || typeof MediaRecorder === 'undefined') { fail(t.errMic); return; }
370	      try {
371	        audioCtx = new AC();
372	        const analyser = audioCtx.createAnalyser();
373	        analyser.fftSize = 1024;
374	        audioCtx.createMediaStreamSource(audio).connect(analyser);
375	        const buf = new Float32Array(analyser.fftSize);
376	        startRecorder();
377	        poll = setInterval(() => tick(analyser, buf, 100), 100);
378	      } catch {
379	        fail(t.errMic);
380	      }
381	    },
382	    setMicMuted(m) {
383	      muted = !!m;
384	      if (!started || ended) return;
385	      emit({ type: 'listening', on: !muted && !aiSpeaking });
386	      if (muted) finishTurn(false);
387	      else resetTurn();
388	    },
389	  };
390	}

