   151	};
   152	
   153	export function buildSummary({ lang = 'zh', triage, vet, insurance }) {
   154	  const L = LABELS[lang] || LABELS.en;
   155	  const lines = [];
   156	  if (triage && triage.summary) lines.push(triage.summary);
   157	  if (vet) {
   158	    lines.push(`${L.plan}: ${vet.time} · ${vet.place}`);
   159	    lines.push(`${L.estimate}: ≈ ${vet.currency || 'CHF'} ${vet.estimate}`);
   160	  }
   161	  if (insurance) {
   162	    const cur = insurance.currency || 'CHF';
   163	    lines.push(
   164	      `${L.insurance}: ${L.back} ≈ ${cur} ${insurance.reimbursed} · ${L.pay} ≈ ${cur} ${insurance.outOfPocket}`
   165	    );
   166	    const no = (insurance.points || []).filter((p) => !p.ok);
   167	    if (no.length) {
   168	      lines.push(`${L.notCovered}: ${no.map((p) => (p.ref ? `${p.text} (${p.ref})` : p.text)).join('; ')}`);
   169	    }
   170	  }
   171	  return lines.join('\n');
